-- Agent memory and technique knowledge base (MEMORY-001, CONTEXT_PACK §3.1, §7, §8.6, §8.7). Generated by
-- `pnpm db:generate --name memories` from src/schema/memories.ts, then reviewed. Forward-only: never edit once
-- applied; add a new migration. Both tables hold vector(384) embeddings with an HNSW cosine index (DB-005).
CREATE TABLE "memories" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"run_id" uuid,
	"scope" text NOT NULL,
	"kind" text NOT NULL,
	"title" text NOT NULL,
	"content" text NOT NULL,
	"embedding" vector(384) NOT NULL,
	"embed_model" text NOT NULL,
	"embed_revision" text NOT NULL,
	"source" text NOT NULL,
	"trust" text DEFAULT 'untrusted' NOT NULL,
	"provenance" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"redacted" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"retention_until" timestamp with time zone,
	"legal_hold" boolean DEFAULT false NOT NULL,
	CONSTRAINT "memories_scope_check" CHECK ("memories"."scope" IN ('run', 'tenant')),
	CONSTRAINT "memories_run_scope_check" CHECK ("memories"."scope" <> 'run' OR "memories"."run_id" IS NOT NULL),
	CONSTRAINT "memories_kind_check" CHECK (length(btrim("memories"."kind")) > 0),
	CONSTRAINT "memories_title_check" CHECK (length(btrim("memories"."title")) > 0),
	CONSTRAINT "memories_content_check" CHECK (length(btrim("memories"."content")) > 0),
	CONSTRAINT "memories_embed_model_check" CHECK (length(btrim("memories"."embed_model")) > 0),
	CONSTRAINT "memories_embed_revision_check" CHECK (length(btrim("memories"."embed_revision")) > 0),
	CONSTRAINT "memories_source_check" CHECK ("memories"."source" IN ('agent', 'operator', 'system', 'external')),
	CONSTRAINT "memories_trust_check" CHECK ("memories"."trust" IN ('untrusted', 'asserted', 'verified')),
	CONSTRAINT "memories_provenance_check" CHECK (jsonb_typeof("memories"."provenance") = 'object')
);
--> statement-breakpoint
ALTER TABLE "memories" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "technique_kb" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"technique_key" text NOT NULL,
	"title" text,
	"body" text,
	"owasp_refs" text[],
	"wstg_refs" text[],
	"cwe_ids" text[],
	"embedding" vector(384) NOT NULL,
	"embed_model" text NOT NULL,
	"embed_revision" text NOT NULL,
	"version" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "technique_kb_technique_key_unique" UNIQUE("technique_key"),
	CONSTRAINT "technique_kb_technique_key_check" CHECK (length(btrim("technique_kb"."technique_key")) > 0),
	CONSTRAINT "technique_kb_embed_model_check" CHECK (length(btrim("technique_kb"."embed_model")) > 0),
	CONSTRAINT "technique_kb_embed_revision_check" CHECK (length(btrim("technique_kb"."embed_revision")) > 0)
);
--> statement-breakpoint
CREATE INDEX "memories_tenant_id_idx" ON "memories" USING btree ("tenant_id");--> statement-breakpoint
CREATE INDEX "memories_tenant_run_idx" ON "memories" USING btree ("tenant_id","run_id");--> statement-breakpoint
CREATE INDEX "memories_tenant_kind_idx" ON "memories" USING btree ("tenant_id","kind");--> statement-breakpoint
CREATE INDEX "memories_tenant_scope_idx" ON "memories" USING btree ("tenant_id","scope");--> statement-breakpoint
CREATE INDEX "memories_dedup_key_idx" ON "memories" USING btree ((("provenance"->>'dedup_key')));--> statement-breakpoint
CREATE INDEX "memories_embedding_hnsw_idx" ON "memories" USING hnsw ("embedding" vector_cosine_ops) WITH (m=16,ef_construction=64);--> statement-breakpoint
CREATE INDEX "technique_kb_embedding_hnsw_idx" ON "technique_kb" USING hnsw ("embedding" vector_cosine_ops) WITH (m=16,ef_construction=64);--> statement-breakpoint
CREATE POLICY "memories_tenant_isolation" ON "memories" AS PERMISSIVE FOR ALL TO public USING (tenant_id = current_setting('app.tenant_id')::uuid) WITH CHECK (tenant_id = current_setting('app.tenant_id')::uuid);--> statement-breakpoint

-- Hand-written below (Drizzle models neither FORCE ROW LEVEL SECURITY, grants nor triggers). Reviewed.
-- memories: the DB-003 canonical policy (above) is the rlsPolicySql('memories') predicate. FORCE makes the owner
-- subject to it too, so nothing reads across tenants, and an unset app.tenant_id fails closed (no missing_ok).
ALTER TABLE "memories" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
REVOKE ALL ON "memories" FROM PUBLIC;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON "memories" TO bw_app;--> statement-breakpoint
-- updated_at follows every change (bw_set_updated_at: 0002_column_mixins).
CREATE TRIGGER memories_set_updated_at BEFORE UPDATE ON "memories" FOR EACH ROW EXECUTE FUNCTION bw_set_updated_at();--> statement-breakpoint
-- technique_kb is platform-global (no tenant_id, no RLS). Default privileges give bw_app all DML on new tables, so
-- what it must not have is taken back: tenants read the curated techniques, and only the pipeline role (the owner)
-- writes them (MEMORY-008).
REVOKE ALL ON "technique_kb" FROM PUBLIC;--> statement-breakpoint
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON "technique_kb" FROM bw_app;--> statement-breakpoint
GRANT SELECT ON "technique_kb" TO bw_app;--> statement-breakpoint
CREATE TRIGGER technique_kb_set_updated_at BEFORE UPDATE ON "technique_kb" FOR EACH ROW EXECUTE FUNCTION bw_set_updated_at();
